import {Bakery,RECIPES,STATIONS} from './model.js';
import {makeScene,imageURLs} from './scene.js';
const $=s=>document.querySelector(s);const SAVE='nemo-bakery-v1';
function readSave(){try{const s=JSON.parse(localStorage.getItem(SAVE));if(!s||s.v!==1)return null;for(const k of ['day','bank','upgrades','best','lifetime'])if(!Number.isFinite(s[k])||s[k]<0)return null;if(s.upgrades>2||s.day<1)return null;return s;}catch{return null;}}
const model=new Bakery(readSave());let scene,uiReady=false,lastUI=0,orderStamp='',toastTimer,modalMode='',resumeAfterModal=false,soundOn=false,audio;
function save(){try{localStorage.setItem(SAVE,JSON.stringify(model.save()));}catch{notice('이 브라우저에서는 기록을 저장할 수 없어요. 현재 게임은 계속할 수 있어요.');}}
function note(freq,duration=.1,delay=0){if(!soundOn)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+delay;o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.055,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+duration);}catch{}}
function notice(text){if(!text)return;$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function doAction(key){const result=model.action(key);notice(result.text);renderUI();}
function goStation(key){if(model.phase==='ready'){notice('가게 문을 열면 시작해요.');return;}scene?.travelStation(key);}
function selectRecipe(id,go=false){model.select(id);document.querySelectorAll('.recipe').forEach((el,i)=>{el.classList.toggle('selected',i===id);el.setAttribute('aria-pressed',String(i===id));});if(go&&model.phase==='running')goStation('prep');renderUI();}
function openModal(html,mode){resumeAfterModal=model.phase==='running';if(resumeAfterModal)model.pause();modalMode=mode;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal-close').style.display=mode==='summary'?'none':'';renderUI();}
function closeModal(){if(modalMode==='summary')return;$('#modal').close();if(resumeAfterModal&&model.phase==='paused')model.pause();resumeAfterModal=false;modalMode='';renderUI();}
function pause(){if(!uiReady||model.phase==='ready'||model.phase==='summary')return;if($('#modal').open){closeModal();return;}openModal('<span class="eyebrow">TAKE A LITTLE BREAK</span><h2 class="modal-title">빵집도 잠깐 쉬는 중.</h2><p class="modal-sub">오븐도, 손님도 기다리고 있어요.<br>준비가 되면 다시 시작해요.</p><button class="primary modal-button" id="resume">계속하기 →</button><button class="restart-link" id="restart-day" style="display:block;margin:20px auto 0;background:none;font-size:11px;color:#ad9271">오늘 장사 다시 시작</button>','pause');$('#resume').onclick=closeModal;$('#restart-day').onclick=()=>{$('#modal').close();resumeAfterModal=false;modalMode='';model.reset();scene.resetPlayer();orderStamp='';$('#welcome').classList.remove('hidden');renderUI();};}
function help(){if(model.phase==='summary')return;openModal('<span class="eyebrow">HOW TO PLAY</span><h2 class="modal-title">마을의 작은 제빵사</h2><ul class="help-list"><li><b>01 · 주문을 보고 반죽하기</b><br>오른쪽 레시피를 고르면 반죽대로 이동해요. 손에 반죽은 하나씩 들 수 있어요.</li><li><b>02 · 오븐에 넣고, 다시 꺼내기</b><br>오븐을 누르면 굽기 시작! 초록 알림이 뜨면 다시 눌러 빵을 꺼내요. 완성 후 18초가 지나면 빵이 타요.</li><li><b>03 · 손님에게 건네기</b><br>판매대를 누르면 주문에 맞는 빵을 자동으로 건네요. 빨리 건네면 팁, 연속 판매하면 추가 보너스!</li><li><b>한 번의 영업은 3분</b><br>하루 정산 후 모은 돈으로 오븐을 늘릴 수 있어요. 날짜·보유금·업그레이드는 이 브라우저에 저장돼요.</li></ul><p class="modal-sub">방향키 / WASD 이동 · E 사용 · 1 / 2 / 3 작업<br>휴대폰은 가구와 작업 버튼을 터치하세요.</p><button id="help-ok" class="primary modal-button">알겠어요</button>','help');$('#help-ok').onclick=closeModal;}
function summary(){const stars=model.revenue>=model.goal?3:model.revenue>=model.goal*.6?2:1;const headline=stars===3?'오늘도, 잘 구웠어요.':stars===2?'따뜻한 하루였어요.':'첫 빵의 기억은 오래가요.';openModal('<span class="eyebrow">DAY '+String(model.day).padStart(2,'0')+' · BAKERY CLOSED</span><h2 class="modal-title">'+headline+'</h2><div class="stars">'+Array.from({length:3},(_,i)=>i<stars?'★':'☆').join('')+'</div><p class="modal-sub">'+(model.revenue>=model.goal?'오늘의 목표를 달성했어요!':'내일은 더 많은 친구들을 만나 봐요.')+'</p><div class="report-grid"><div><small>오늘 매출</small><b>'+model.revenue+' G</b></div><div><small>행복한 손님</small><b>'+model.served+'명</b></div><div><small>최고 연속 판매</small><b>'+model.maxCombo+'번</b></div><div><small>최고 하루 매출</small><b>'+model.best+' G</b></div></div><div class="bank-line">모아 둔 돈 <b id="bank">'+model.bank+' G</b></div><div id="upgrade-panel"></div><button id="next-day" class="primary">다음 날 준비하기 →</button><p class="saved-note">장사 기록을 이 브라우저에 저장했어요.</p>','summary');renderUpgrade();$('#next-day').onclick=()=>{$('#modal').close();modalMode='';model.nextDay();scene.resetPlayer();orderStamp='';$('#welcome').classList.remove('hidden');$('#welcome h1').innerHTML='새로운 아침,<br>따뜻한 시작.';$('#start').innerHTML='DAY '+String(model.day).padStart(2,'0')+' 문 열기 <span>→</span>';renderUI();};save();}
function renderUpgrade(){const cost=model.upgrades===0?90:170;$('#upgrade-panel').innerHTML=model.upgrades>=2?'<div class="upgrade"><b>작은 빵집의 모든 준비 완료!</b><small>2칸 오븐 · 빠른 반죽과 굽기</small></div>':'<div class="upgrade"><b>'+(model.upgrades===0?'오븐 한 칸 더':'숙련된 제빵사')+'</b><small>'+(model.upgrades===0?'빵 두 개를 동시에 구워요.':'반죽과 굽기가 더 빨라져요.')+'</small><button id="buy" '+(model.bank<cost?'disabled':'')+'>'+cost+' G · 개선하기</button></div>';if($('#buy'))$('#buy').onclick=()=>{if(model.buyUpgrade()){save();$('#bank').textContent=model.bank+' G';renderUpgrade();note(659,.2);note(880,.3,.1);}};}
function processEvents(){while(model.events.length){const e=model.events.shift();if(e.type==='notice')notice(e.text);if(e.type==='mixed'){notice('반죽 완성! 이제 오븐에 넣어 주세요.');note(440);note(554,.15,.1);}if(e.type==='baked'){notice('딩! 빵이 다 익었어요. 오븐에서 꺼내 주세요.');note(784,.3);note(1047,.4,.15);}if(e.type==='collect'){scene.pop('+1',730,199,'#758e55');note(660,.15);}if(e.type==='sold'){scene.pop('+'+e.amount+' G',282,390,'#b88a43');note(523,.2);note(659,.2,.1);note(784,.3,.2);if(model.combo>1)$('#combo').textContent=model.combo+' combo!';}if(e.type==='arrive')note(554,.12);if(e.type==='close')summary();}}
function buildUI(){const root=$('#recipes');root.innerHTML=RECIPES.map(r=>'<button class="recipe '+(r.id===model.selected?'selected':'')+'" data-recipe="'+r.id+'" aria-pressed="'+(r.id===model.selected)+'" aria-label="'+r.name+' 선택하고 반죽하기"><img src="'+imageURLs['p'+r.id]+'" alt=""><span><b>'+r.name+'</b><small>'+r.desc+'</small><span class="recipe-price">'+r.price+' G <span style="color:#b7a48c;font-weight:400"> / '+r.bake+'초</span></span></span></button>').join('');root.querySelectorAll('button').forEach(el=>el.onclick=()=>selectRecipe(Number(el.dataset.recipe),true));$('#inventory').innerHTML=RECIPES.map(r=>'<div class="stock-item" data-stock="'+r.id+'" title="'+r.name+'"><img src="'+imageURLs['p'+r.id]+'" alt="'+r.name+'"><span>0</span></div>').join('');uiReady=true;$('#loading').classList.add('hidden');$('#welcome').classList.remove('hidden');renderUI();}
function renderUI(){if(!uiReady)return;document.querySelectorAll('.recipe').forEach((el,i)=>{el.classList.toggle('selected',i===model.selected);el.setAttribute('aria-pressed',String(i===model.selected));});$('#day').textContent='DAY '+String(model.day).padStart(2,'0');$('#day-name').textContent=['나의 작은 빵집','빵 냄새 가득한 아침','또 오고 싶은 빵집'][Math.min(model.day-1,2)];const min=9*60+Math.floor((180-model.time)*3);$('#clock').textContent=String(Math.floor(min/60)).padStart(2,'0')+':'+String(min%60).padStart(2,'0');$('#remaining').textContent=model.phase==='ready'?'영업 준비 중':model.phase==='paused'?'잠시 쉬는 중':model.phase==='summary'?'오늘 영업 끝':Math.ceil(model.time)+'초 후 영업 종료';$('#time-fill').style.width=model.time/180*100+'%';$('#revenue').textContent=model.revenue;$('#goal-label').textContent=model.revenue>=model.goal?'목표 달성! ♡':'오늘의 목표 '+model.goal+' G';$('#goal-fill').style.width=Math.min(100,model.revenue/model.goal*100)+'%';$('#world-status').textContent={ready:'OPEN SOON',running:'FRESHLY BAKED',paused:'TAKE A BREAK',summary:'SEE YOU TOMORROW'}[model.phase];$('#order-count').textContent=model.orders.length+' / 3';
 const stamp=model.orders.map(o=>o.id).join(',');if(stamp!==orderStamp||!$('#orders').children.length){orderStamp=stamp;$('#orders').innerHTML=model.orders.length?model.orders.map(o=>'<button class="order-ticket" data-order="'+o.id+'" title="'+RECIPES[o.recipe].name+' 주문"><img src="'+imageURLs['c'+o.chef]+'" alt=""><span class="order-info"><b>'+RECIPES[o.recipe].name+'</b><small>'+o.name+' · 한 개 주세요</small></span><img class="order-recipe-img" src="'+imageURLs['p'+o.recipe]+'" alt=""><span class="patience"><i></i></span></button>').join(''):'<div class="empty-order">'+(model.phase==='ready'?'문을 열면, 빵 냄새를 따라 손님들이 찾아와요.':'다음 손님이 빵 냄새를 따라 오고 있어요.')+'</div>';document.querySelectorAll('.order-ticket').forEach(el=>el.onclick=()=>{const o=model.orders.find(o=>o.id===Number(el.dataset.order));if(!o)return;if(model.stock[o.recipe]>0)goStation('serve');else selectRecipe(o.recipe,true);});}
 model.orders.forEach(o=>{const el=$('[data-order="'+o.id+'"]');if(!el)return;el.classList.toggle('ready',model.stock[o.recipe]>0);el.querySelector('i').style.width=Math.max(0,o.left/o.max*100)+'%';el.querySelector('i').style.background=o.left<20?'#cb8a7f':'#9eaf83';});
 document.querySelectorAll('[data-stock]').forEach((el,i)=>{el.classList.toggle('filled',model.stock[i]>0);el.querySelector('span').textContent=model.stock[i];});const stockCount=model.stock.reduce((a,b)=>a+b,0);$('#stock-count').textContent=stockCount+'개';$('#tray-hint').textContent=stockCount?'주문과 맞는 빵을 판매대에서 건네 주세요.':'오븐에서 꺼낸 빵이 여기 담겨요.';
 $('#prep-state').textContent=model.mixing?'반죽하는 중…':model.dough!==null?'반죽을 들고 있어요':RECIPES[model.selected].name;const ready=model.ovens.some(o=>o?.ready),busy=model.ovens.find(o=>o&&!o.ready),empty=model.ovens.some(o=>!o),canSell=model.orders.some(o=>model.stock[o.recipe]>0);
 $('#oven-label').textContent=ready?'구운 빵 꺼내기':'오븐에 넣기';$('#oven-state').textContent=ready?'완성! 따끈할 때 꺼내요':busy?'굽는 중 · '+Math.ceil(Math.max(0,busy.duration-busy.elapsed))+'초':model.dough!==null?'반죽이 준비됐어요':'반죽을 먼저 준비해요';$('#serve-state').textContent=canSell?'기다리는 손님에게 전달!':'갓 구운 빵을 기다려요';$('#bake-progress').style.width=ready?'100%':busy?Math.min(100,busy.elapsed/busy.duration*100)+'%':'0%';$('#prep-btn').classList.toggle('active',model.dough===null&&!model.mixing&&!ready&&!canSell);$('#oven-btn').classList.toggle('active',ready||(model.dough!==null&&empty));$('#serve-btn').classList.toggle('active',canSell);
 let hint='주문표를 누르면 필요한 레시피를 골라 반죽대로 이동해요.';if(model.phase==='ready')hint='첫 손님은 <b>딸기 도넛</b>을 좋아해요.<br>레시피를 골라 반죽을 시작해 봐요.';else if(ready)hint='<b>딩! 오븐의 초록 불</b>을 확인해요.<br>다 익은 빵은 18초 안에 꺼내 주세요.';else if(canSell)hint='완성된 빵을 기다리는 친구가 있어요.<br><b>판매대</b>로 가서 건네 주세요!';else if(model.dough!==null)hint='반죽을 들고 있어요.<br><b>오븐</b>을 눌러 노릇하게 구워 봐요.';else if(busy)hint='빵이 익는 동안 다음 반죽을 준비하면<br>더 많은 손님을 맞이할 수 있어요.';$('#hint').innerHTML=hint;
 if(model.combo<2)$('#combo').textContent='';$('#pause').setAttribute('aria-label',model.phase==='paused'?'계속하기':'일시정지');}
const callbacks={ready:s=>{scene=s;buildUI();},error:text=>{$('#loading').innerHTML='<div class="loader-error">'+text+'</div>';},notice,action:doAction,pause,frame:dt=>{processEvents();lastUI+=dt;if(lastUI>.12){lastUI=0;renderUI();}}};
const game=new Phaser.Game({type:Phaser.CANVAS,parent:'game',width:960,height:600,backgroundColor:'#aebf91',pixelArt:true,antialias:false,roundPixels:true,scale:{mode:Phaser.Scale.FIT,autoCenter:Phaser.Scale.CENTER_BOTH},audio:{noAudio:true},fps:{target:60,forceSetTimeOut:true,smoothStep:false},scene:makeScene(model,callbacks),banner:false});
$('#start').onclick=()=>{model.start();$('#welcome').classList.add('hidden');note(523,.15);note(659,.2,.12);renderUI();};document.querySelectorAll('[data-station]').forEach(el=>el.onclick=()=>goStation(el.dataset.station));$('#pause').onclick=pause;$('#help').onclick=help;$('#modal-close').onclick=closeModal;$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});$('#sound').onclick=()=>{soundOn=!soundOn;$('#sound .mute-dot').style.display=soundOn?'none':'';$('#sound').setAttribute('aria-label',soundOn?'효과음 끄기':'효과음 켜기');if(soundOn)note(659,.2);};document.addEventListener('visibilitychange',()=>{if(document.hidden&&model.phase==='running')pause();});
// Read-only diagnostics for reproducible QA without mutating gameplay.
window.bakerySnapshot=()=>JSON.parse(JSON.stringify({phase:model.phase,day:model.day,time:model.time,player:model.player,dough:model.dough,ovens:model.ovens,stock:model.stock,orders:model.orders,revenue:model.revenue,served:model.served,path:scene?.path}));
